create or replace function public.approve_application(p_id uuid,p_cv uuid,p_cover uuid) returns text language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); a public.applications%rowtype; latest_cv uuid; latest_cover uuid; begin if uid is null then return 'not_found'; end if; select * into a from public.applications where id=p_id and user_id=uid for update; if not found then return 'not_found'; end if; if a.status not in ('saved','preparing','review_required','action_required') or exists(select 1 from public.manual_submissions where application_id=p_id) then return 'invalid_state'; end if; select id into latest_cv from public.application_documents where application_id=p_id and user_id=uid and kind='cv' order by created_at desc,id desc limit 1; select id into latest_cover from public.application_documents where application_id=p_id and user_id=uid and kind='cover_letter' order by created_at desc,id desc limit 1; if p_cv is distinct from latest_cv or p_cover is distinct from latest_cover then return 'invalid_document'; end if; insert into public.application_approvals(application_id,user_id,cv_document_id,cover_document_id) values(p_id,uid,p_cv,p_cover); update public.applications set status='action_required',updated_at=now() where id=p_id; insert into public.application_events(application_id,user_id,event) values(p_id,uid,'Preparation approved for manual handoff'); return 'approved'; end $$;
create or replace function public.record_manual_application(p_id uuid,p_approval uuid,p_evidence text) returns text language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); a public.applications%rowtype; approval public.application_approvals%rowtype; latest_cv uuid; latest_cover uuid; begin if uid is null then return 'not_found'; end if; if p_evidence is null or length(trim(p_evidence)) not between 3 and 1000 then return 'invalid_evidence'; end if; select * into a from public.applications where id=p_id and user_id=uid for update; if not found then return 'not_found'; end if; if exists(select 1 from public.manual_submissions where application_id=p_id) then return 'already_recorded'; end if; select * into approval from public.application_approvals where id=p_approval and application_id=p_id and user_id=uid; if a.status<>'action_required' or not found then return 'invalid_state'; end if; select id into latest_cv from public.application_documents where application_id=p_id and user_id=uid and kind='cv' order by created_at desc,id desc limit 1; select id into latest_cover from public.application_documents where application_id=p_id and user_id=uid and kind='cover_letter' order by created_at desc,id desc limit 1; if approval.cv_document_id is distinct from latest_cv or approval.cover_document_id is distinct from latest_cover then return 'approval_outdated'; end if; insert into public.manual_submissions(application_id,user_id,approval_id,evidence) values(p_id,uid,p_approval,trim(p_evidence)); update public.applications set status='applied',updated_at=now() where id=p_id; insert into public.application_events(application_id,user_id,event) values(p_id,uid,'External submission self-reported by user'); return 'recorded'; end $$;
